import{_ as n,o as t,c as r,a2 as a}from"./chunks/framework.vLhlLNVn.js";const i="/assets/einstellungen-optionen.C71V9hNg.png",s="/assets/wiederholungen-zeitachse.L9BYPwmP.svg",f=JSON.parse('{"title":"Instanzeinstellungen","description":"","frontmatter":{"order":1,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/de/03.referenz/01.instanz-einstellungen.md"},"headers":[],"relativePath":"de/adapter/wled/referenz/instanz-einstellungen.md","filePath":"de/adapter/wled/referenz/instanz-einstellungen.md","lastUpdated":null}'),l={name:"de/adapter/wled/referenz/instanz-einstellungen.md"};function d(u,e,o,h,c,g){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="instanzeinstellungen" tabindex="-1">Instanzeinstellungen <a class="header-anchor" href="#instanzeinstellungen" aria-label="Permalink to &quot;Instanzeinstellungen&quot;">​</a></h1><p><a id="polling-interval-auto-discovery"></a></p><h2 id="wo-stelle-ich-polling-intervall-und-auto-erkennung-ein" tabindex="-1">Wo stelle ich Polling-Intervall und Auto-Erkennung ein? <a class="header-anchor" href="#wo-stelle-ich-polling-intervall-und-auto-erkennung-ein" aria-label="Permalink to &quot;Wo stelle ich Polling-Intervall und Auto-Erkennung ein?&quot;">​</a></h2><p><strong>Kurz:</strong> Es gibt genau ein Intervall: „Intervall in Sekunden“ in den Instanzeinstellungen, voreingestellt sind 30 Sekunden. Eine Einstellung für die automatische Erkennung gibt es in v0.9.2 nicht. Der Adapter sucht nur beim Start der Instanz nach Geräten und wenn du die Suche von Hand startest, nicht in einem festen Takt.</p><h3 id="die-einstellungen-bis-v0-9-3" tabindex="-1">Die Einstellungen bis v0.9.3 <a class="header-anchor" href="#die-einstellungen-bis-v0-9-3" aria-label="Permalink to &quot;Die Einstellungen bis v0.9.3&quot;">​</a></h3><p>Du findest sie im Admin unter „Instanzen“ in den Einstellungen von <code>wled.&lt;Instanz&gt;</code>:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Voreinstellung</th><th>Wofür</th></tr></thead><tbody><tr><td>„Intervall in Sekunden“</td><td>30</td><td>Takt, in dem der Adapter jedes Gerät prüft, und Grundwert für die Wartezeit bei Wiederholungen</td></tr><tr><td>„Maximale Wiederholungsversuche“</td><td>5</td><td>Fehlversuche, nach denen der Adapter ein Gerät nur noch stündlich prüft</td></tr><tr><td>„Exponentiellen Backoff aktivieren“</td><td>an</td><td>Wartezeit nach jedem Fehlversuch verdoppeln</td></tr></tbody></table><p>Die beiden Einstellungen für Wiederholungen erklärt der nächste Abschnitt: <a href="#often-adapter-retry-offline-device">Wie oft versucht der Adapter ein Offline-Gerät erneut zu erreichen?</a></p><h3 id="was-das-intervall-bewirkt" tabindex="-1">Was das Intervall bewirkt <a class="header-anchor" href="#was-das-intervall-bewirkt" aria-label="Permalink to &quot;Was das Intervall bewirkt&quot;">​</a></h3><p>Ob ein Gerät ständig abgefragt wird, hängt davon ab, ob es per WebSocket verbunden ist:</p><ul><li><strong>Mit WebSocket</strong> (WLED ab 0.12, der Normalfall): Änderungen am Gerät schickt WLED sofort. Das Intervall dient nur der Überwachung. Der Adapter sendet in diesem Takt ein <code>ping</code> an das Gerät. Kommt innerhalb eines Intervalls kein <code>pong</code> zurück, gilt das Gerät als offline, und der Adapter schließt die Verbindung.</li><li><strong>Ohne WebSocket</strong> (ältere Firmware oder nach einem Verbindungsabbruch): Der Adapter fragt das Gerät in diesem Takt per HTTP ab. Änderungen, die du direkt in WLED machst, siehst du in ioBroker dann erst nach bis zu einem Intervall.</li></ul><p>Ein kürzeres Intervall erkennt Ausfälle schneller, erzeugt aber mehr Netzverkehr zu jedem Gerät. Für die meisten Installationen passen die voreingestellten 30 Sekunden.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Stell das Intervall nicht auf 0. In v0.9.2 laufen die Prüfungen dann ohne Pause hintereinander, die Last steigt stark und der Adapter reagiert nicht mehr. Das Eingabefeld lässt 0 zu.</p></div><p><strong>Ab v0.9.3:</strong> Ein Intervall unter 1 Sekunde oder ein leeres Feld ersetzt der Adapter beim Start durch 30 Sekunden und warnt einmal: <code>Invalid polling interval &quot;0&quot;, using 30 seconds</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/924" target="_blank" rel="noreferrer">#924</a>).</p><h3 id="auto-erkennung" tabindex="-1">Auto-Erkennung <a class="header-anchor" href="#auto-erkennung" aria-label="Permalink to &quot;Auto-Erkennung&quot;">​</a></h3><p>Die Suche per Bonjour (mDNS) läuft beim Start der Instanz und wenn du im „Konfig-Manager“ (in älteren Admin-Versionen „Geräte“) auf „Neue Geräte suchen“ klickst. Einen Takt dafür kannst du nicht einstellen. Schritt 3 der Anleitung in der README sprach bis v0.9.2 von „auto-detect cycles“. Das war falsch, es gab nie einen solchen Takt.</p><h3 id="ab-v0-10-0" tabindex="-1">Ab v0.10.0 <a class="header-anchor" href="#ab-v0-10-0" aria-label="Permalink to &quot;Ab v0.10.0&quot;">​</a></h3><p><strong>Ab v0.10.0:</strong> Die Instanzeinstellungen sind neu aufgebaut und haben zwei Reiter: „Geräte“ mit der Geräteliste und „Einstellungen“ (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/266" target="_blank" rel="noreferrer">#266</a>). Im Reiter „Einstellungen“ stehen:</p><table tabindex="0"><thead><tr><th>Bereich</th><th>Einstellung</th><th>Voreinstellung</th><th>Wofür</th></tr></thead><tbody><tr><td>„Verbindung“</td><td>„Abfrage-Intervall“ (s)</td><td>30</td><td>wie „Intervall in Sekunden“ oben, mindestens 1</td></tr><tr><td>„Verbindung“</td><td>„Maximale Wiederholungsversuche“</td><td>5</td><td>wie oben, 1 bis 20</td></tr><tr><td>„Verbindung“</td><td>„Wartezeit nach jedem Fehlversuch verlängern (exponentielles Backoff)“</td><td>an</td><td>wie oben</td></tr><tr><td>„Erkennung“</td><td>„Geräte automatisch per Bonjour/mDNS suchen“</td><td>an</td><td>aus: keine Suche beim Start, nur bekannte und per IP-Adresse hinzugefügte Geräte (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/897" target="_blank" rel="noreferrer">#897</a>)</td></tr><tr><td>„Befehle“</td><td>„Wartezeit zum Bündeln von Befehlen je Gerät“ (ms)</td><td>50</td><td>Änderungen am selben Gerät innerhalb dieser Zeit gehen als ein Befehl raus, 0 = nie bündeln, höchstens 1000 (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/926" target="_blank" rel="noreferrer">#926</a>)</td></tr></tbody></table><p><img src="'+i+'" alt="Reiter „Einstellungen“ der Instanz mit „Abfrage-Intervall“, „Maximale Wiederholungsversuche“, Backoff, „Geräte automatisch per Bonjour/mDNS suchen“ und „Wartezeit zum Bündeln von Befehlen je Gerät“"></p><p><strong>Ab v0.10.0:</strong> Ist die automatische Suche aus, findest du neue Geräte weiterhin von Hand, in den Instanzeinstellungen im Reiter „Geräte“ über „Geräte suchen“ (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/897" target="_blank" rel="noreferrer">#897</a>).</p><p><strong>Ab v0.10.0:</strong> Das Bündeln lässt sich zusätzlich je Gerät abschalten, über den Datenpunkt <code>wled.&lt;Instanz&gt;.&lt;MAC&gt;.bundleCommands</code> oder im Konfig-Manager unter „Gerät bearbeiten“ mit dem Haken „Kurz aufeinander folgende Befehle bündeln“. Wann das sinnvoll ist, steht unter <a href="./../fehlerbehebung/befehle-wirken-nicht#several-commands-quick-succession-lead">Warum führen mehrere Befehle kurz hintereinander zu ETIMEDOUT?</a> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/926" target="_blank" rel="noreferrer">#926</a>).</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erstes-geraet#adapter-wled-devices-automatically">Wie und wann findet der Adapter meine WLED-Geräte automatisch?</a> · <a href="./../hintergrund/verbindung-und-aktualisierung#states-only-updated-after-30">Warum werden Zustände erst nach 30 Sekunden aktualisiert?</a></p><p><a id="often-adapter-retry-offline-device"></a></p><h2 id="wie-oft-versucht-der-adapter-ein-offline-gerat-erneut-zu-erreichen-und-welche-einstellungen-gibt-es" tabindex="-1">Wie oft versucht der Adapter ein Offline-Gerät erneut zu erreichen, und welche Einstellungen gibt es? <a class="header-anchor" href="#wie-oft-versucht-der-adapter-ein-offline-gerat-erneut-zu-erreichen-und-welche-einstellungen-gibt-es" aria-label="Permalink to &quot;Wie oft versucht der Adapter ein Offline-Gerät erneut zu erreichen, und welche Einstellungen gibt es?&quot;">​</a></h2><p><strong>Kurz:</strong> Antwortet ein Gerät nicht, versucht es der Adapter erneut, zuerst nach einem Intervall (voreingestellt 30 Sekunden), danach mit immer längeren Pausen. Nach 5 Fehlversuchen prüft er das Gerät nur noch einmal pro Stunde. Einstellen kannst du das Intervall, die Zahl der Versuche und ob die Pausen länger werden. Die Einstellungen gelten für alle Geräte der Instanz gemeinsam.</p><h3 id="die-einstellungen" tabindex="-1">Die Einstellungen <a class="header-anchor" href="#die-einstellungen" aria-label="Permalink to &quot;Die Einstellungen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Einstellung</th><th>Voreinstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td>„Intervall in Sekunden“</td><td>30</td><td>Abstand zwischen zwei Prüfungen und Grundwert der Pause nach einem Fehlversuch</td></tr><tr><td>„Maximale Wiederholungsversuche“</td><td>5</td><td>Nach so vielen Fehlversuchen hintereinander prüft der Adapter das Gerät nur noch einmal pro Stunde. Erlaubt sind 1 bis 20.</td></tr><tr><td>„Exponentiellen Backoff aktivieren“</td><td>an</td><td>Die Pause verdoppelt sich nach jedem Fehlversuch, höchstens bis 10 Minuten. Aus: Die Pause bleibt immer ein Intervall.</td></tr></tbody></table><h3 id="so-lauft-ein-ausfall-ab" tabindex="-1">So läuft ein Ausfall ab <a class="header-anchor" href="#so-lauft-ein-ausfall-ab" aria-label="Permalink to &quot;So läuft ein Ausfall ab&quot;">​</a></h3><p>Mit den Voreinstellungen sieht das so aus:</p><ol><li>Das Gerät antwortet nicht. Das ist Fehlversuch 1, die nächste Prüfung folgt nach 30 Sekunden.</li><li>Bleibt es stumm, folgen die nächsten Prüfungen nach 60, 120, 240 und 480 Sekunden. Nach dem 5. Fehlversuch, gut 7 Minuten nach dem ersten, ist die Grenze erreicht.</li><li>Etwa eine Viertelstunde nach dem ersten Fehlversuch stellt der Adapter auf die lange Pause um und prüft das Gerät erst eine Stunde später wieder.</li><li>Nach dieser Stunde setzt er den Zähler zurück und beginnt wieder bei Schritt 1.</li><li>Antwortet das Gerät bei einer Prüfung, setzt der Adapter den Zähler sofort zurück und verbindet sich wieder.</li></ol><p><img src="'+s+'" alt="Zeitachse mit den Voreinstellungen: Nach dem ersten Fehlversuch prüft der Adapter nach 30 Sekunden, dann nach 60, 120, 240 und 480 Sekunden erneut. Nach 5 Fehlversuchen wartet er eine Stunde und beginnt dann von vorn."></p><p>Der Adapter merkt also erst bei der nächsten Prüfung, dass ein Gerät wieder da ist. Nach einem kurzen Ausfall dauert das höchstens einige Minuten. War das Gerät länger aus, kann es bis zu einer Stunde dauern. Brauchst du es sofort, starte die Instanz neu. Dann verbindet sich der Adapter gleich beim Start mit allen bekannten Geräten.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Schaltest du ein Gerät oft für längere Zeit aus, etwa eine Weihnachtsbeleuchtung, sind mehr Versuche oder ein ausgeschalteter Backoff hilfreich. Dann bemerkt der Adapter das Gerät nach dem Einschalten schneller, prüft es aber auch öfter, solange es aus ist.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Die Einstellungen gelten für alle Geräte der Instanz gemeinsam. Eine Einstellung je Gerät gibt es nicht.</p></div><h3 id="was-im-log-steht" tabindex="-1">Was im Log steht <a class="header-anchor" href="#was-im-log-steht" aria-label="Permalink to &quot;Was im Log steht&quot;">​</a></h3><p><strong>Bis v0.9.2:</strong> Bei jedem Fehlversuch steht <code>Unable to initialise 192.168.x.y will retry in scheduled interval !</code> als Warnung im Log. Die ersten drei Versuche stehen zusätzlich als Info, zum Beispiel <code>Device 192.168.x.y unavailable (attempt 1/5), will retry in 30 seconds</code>. Die lange Pause nach der Grenze steht nur auf der Stufe „debug“: <code>Device 192.168.x.y has failed 5 consecutive times, next retry in 1 hour</code>.</p><p><strong>Ab v0.9.3:</strong> Ein Ausfall steht nur einmal als Warnung im Log. Alle weiteren Versuche stehen auf der Stufe „debug“ (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/903" target="_blank" rel="noreferrer">#903</a>, <a href="https://github.com/DrozmotiX/ioBroker.wled/issues/788" target="_blank" rel="noreferrer">#788</a>). Ein Polling-Intervall unter 1 Sekunde oder eine ungültige Zahl an Versuchen ersetzt der Adapter beim Start durch die Voreinstellung (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/924" target="_blank" rel="noreferrer">#924</a>).</p><p><strong>Ab v0.10.0:</strong> Schreibst du einen Befehl an ein Gerät, das gerade als offline gilt, versucht der Adapter sofort, es neu zu verbinden, statt auf die nächste Prüfung zu warten. Ist das Gerät wieder da, geht der Befehl gleich raus. Zwei solche Versuche liegen mindestens 5 Sekunden auseinander (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/939" target="_blank" rel="noreferrer">#939</a>).</p><p><strong>Ab v0.10.0:</strong> Die Einstellungen heißen „Abfrage-Intervall“, „Maximale Wiederholungsversuche“ und „Wartezeit nach jedem Fehlversuch verlängern (exponentielles Backoff)“. Sie stehen in den Instanzeinstellungen im Reiter „Einstellungen“, Bereich „Verbindung“ (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/266" target="_blank" rel="noreferrer">#266</a>).</p><p><strong>Siehe auch:</strong> <a href="./../fehlerbehebung/verbindung-und-start#wled-shown-offline-after-restart">Warum wird WLED nach Neustart oder Update als offline angezeigt?</a> · <a href="./../anleitungen/geraete-verwalten#deal-switched-off-offline-devices">Wie gehe ich mit ausgeschalteten oder offline Geräten um?</a> · <a href="./../hintergrund/verbindung-und-aktualisierung#tell-whether-device-really-online">Woran sehe ich, ob ein Gerät wirklich online ist?</a></p>',41)])])}const m=n(l,[["render",d]]);export{f as __pageData,m as default};
